"""Build the static multi-page company website from the approved brochure content."""
from pathlib import Path
import re
from html import escape

ROOT = Path(__file__).parent
PUBLIC = ROOT / 'public'
ORIGIN = 'https://shakthi-enterprises-2df21.web.app'
original = (ROOT / 'content-original.html').read_text(encoding='utf-8')
sections = re.findall(r'<section\b.*?</section>', original, re.S)
def section(key):
    return next(s for s in sections if f'id="{key}"' in s)
def class_section(key):
    return next(s for s in sections if f'class="{key}"' in s)

routes = [('Home','/'),('Our story','/about'),('Services','/services'),('Infrastructure','/infrastructure'),('Materials','/materials'),('Quality','/quality'),('Catalogue','/catalogue')]
def header(active):
    links = ''.join(f'<a href="{url}" {"aria-current=page" if active==url else ""}>{label}</a>' for label,url in routes)
    return f'''<a class="skip" href="#main">Skip to content</a><div class="topbar"><div class="wrap"><span>PRECISION MANUFACTURING · BANGALORE, INDIA</span><a href="tel:+919902831454">LET’S TALK: +91 99028 31454 ↗</a></div></div><header class="header"><nav class="wrap nav" aria-label="Main navigation"><a class="brand" href="/" aria-label="Shakthi Enterprises home"><img src="/assets/logo.webp" alt="Shakthi Enterprises" width="154" height="85"></a><button class="menu-toggle" aria-expanded="false" aria-controls="nav-links">Menu <span>☰</span></button><div class="nav-links" id="nav-links">{links}<a href="/contact" class="button small">Enquire <span>↗</span></a></div></nav><div class="reading-progress" aria-hidden="true"></div></header>'''
def footer():
    links=''.join(f'<a href="{url}">{label}</a>' for label,url in routes[1:])
    return f'''<footer><div class="wrap footer-top"><div><a class="footer-brand" href="/">SHAKTHI <span>ENTERPRISES</span></a><p>Precision in Plastic. Strength in Every Part.</p><p>Bangalore, India · Established 2006</p></div><div class="footer-links">{links}<a href="/contact">Contact</a></div><img class="blessing" src="/assets/blessing.webp" alt="Lord Ayyappa" width="560" height="741" loading="lazy"></div><div class="wrap footer-bottom"><span>© <span id="year">2026</span> Shakthi Enterprises.</span><span>GSTIN: 29BJLPS7037J1ZG · UDYAM-KR-03-0112044</span><span>Manufactured in India.</span></div></footer><a class="floating-contact" href="https://wa.me/919902831454" target="_blank" rel="noopener" aria-label="Chat on WhatsApp"><span>◉</span> Let’s talk</a><dialog class="image-dialog" id="image-dialog"><button class="dialog-close" aria-label="Close enlarged image">Close ×</button><img alt=""><p></p></dialog>'''
def cta(title='Have a part in mind? Let’s make it happen.', text='Bring your drawing, model or sample. We’ll help you plan the next step.'):
    return f'<section class="project-cta"><div class="wrap"><div><p class="eyebrow">YOUR NEXT PROJECT</p><h2>{title}</h2><p>{text}</p></div><a class="button" href="/contact">Discuss your requirement <span>↗</span></a></div></section>'
def banner(kicker,title,description,image):
    return f'''<section class="page-banner"><img src="/assets/{image}" alt="" fetchpriority="high"><div class="wrap"><p class="breadcrumb"><a href="/">Home</a> <span>/</span> {kicker}</p><p class="eyebrow">SHAKTHI ENTERPRISES / {kicker.upper()}</p><h1>{title}</h1><p>{description}</p></div><span class="banner-index">PRECISION / PURPOSE / PARTNERSHIP</span></section>'''
def cards(items, title, kicker='A CLOSER LOOK'):
    return '<section class="section"><div class="wrap"><p class="eyebrow">'+kicker+'</p><h2>'+title+'</h2><div class="editorial-grid">'+''.join(f'<article class="editorial-card"><span>{i+1:02d}</span><h3>{heading}</h3><p>{body}</p></article>' for i,(heading,body) in enumerate(items))+'</div></div></section>'
def photo_feature(image,kicker,title,text,link='/contact',label='Discuss your project'):
    return f'<section class="section feature-section"><div class="wrap split"><img class="feature-photo" src="/assets/{image}" alt="{escape(kicker)}" width="1024" height="781" loading="lazy"><div><p class="eyebrow">{kicker}</p><h2>{title}</h2><p>{text}</p><a class="text-link" href="{link}">{label} ↗</a></div></div></section>'
def document(slug,title,description,content,extra_script=''):
    path='/' if slug=='index' else '/'+slug
    for anchor,route in [('about','about'),('services','services'),('process','services'),('machinery','infrastructure'),('materials','materials'),('quality','quality'),('contact','contact')]:
        content=content.replace(f'href="#{anchor}"',f'href="/{route}#{anchor}"')
    content=content.replace('href="/#contact"','href="/contact"')
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Shakthi Enterprises</title><meta name="description" content="{escape(description)}"><meta name="theme-color" content="#082d46"><link rel="canonical" href="{ORIGIN}{path}"><meta property="og:title" content="{escape(title)} | Shakthi Enterprises"><meta property="og:description" content="{escape(description)}"><meta property="og:image" content="{ORIGIN}/assets/factory.webp"><meta property="og:type" content="website"><link rel="icon" href="/assets/favicon.png"><link rel="preload" href="/assets/nunito-latin.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/styles.css?v=nunito"><link rel="stylesheet" href="/experience.css?v=book2"><script src="/app.js" defer></script><script src="/experience.js" defer></script>{extra_script}</head><body class="page-{slug}">{header(path)}<main id="main">{content}</main>{footer()}</body></html>'''
    (PUBLIC / (slug+'.html')).write_text(html,encoding='utf-8')

slides=[('factory.webp','ENGINEERING YOUR NEXT IDEA','Turning ideas into<br><em>quality components.</em>','Tool design, mould development and plastic injection moulding. One manufacturing partner, from the first drawing to the finished part.','/services','Explore our capabilities'),('production.webp','FROM FIRST ARTICLE TO PRODUCTION','Built for precision.<br><em>Ready for production.</em>','A 40–530 tonne moulding machine range. Flexible production, from short runs to high volumes, with components up to 2.2 kg.','/infrastructure','Inside our infrastructure'),('tooling-floor.webp','THE DETAILS MAKE THE DIFFERENCE','Thoughtful design.<br><em>Dependable tooling.</em>','Part reviews, mould development, machining and inspection, connected through an experienced in-house team.','/quality','Our quality approach')]
hero='''<section class="cinema-hero" aria-label="Manufacturing highlights" aria-roledescription="carousel"><div class="hero-slides">'''+''.join(f'''<article class="hero-slide {"is-active" if i==0 else ""}" aria-hidden="{str(i!=0).lower()}" aria-label="Slide {i+1} of 3"><img src="/assets/{image}" alt="{['Shakthi Enterprises factory exterior','Injection moulding production area','Tooling and inspection workspace'][i]}" {"fetchpriority=high" if i==0 else "loading=eager"}><div class="wrap slide-copy"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p>{body}</p><div class="buttons"><a class="button" href="{link}" {"tabindex=-1" if i else ""}>{label} <span>↗</span></a><a class="hero-catalogue" href="/catalogue" {"tabindex=-1" if i else ""}>View animated catalogue →</a></div></div></article>''' for i,(image,kicker,title,body,link,label) in enumerate(slides))+'''</div><div class="wrap carousel-bar"><div><span class="carousel-label">DISCOVER SHAKTHI</span><span id="slide-number" aria-live="off">01 / 03</span></div><div class="carousel-controls"><button id="slide-prev" aria-label="Previous highlight">←</button><div class="carousel-dots">'''+''.join(f'<button data-slide="{i}" aria-label="Show highlight {i+1}" aria-pressed="{str(i==0).lower()}"><span>0{i+1}</span></button>' for i in range(3))+'''</div><button id="slide-next" aria-label="Next highlight">→</button><button id="slide-pause" aria-label="Pause slideshow" aria-pressed="false">Ⅱ</button></div></div><a href="#overview" class="scroll-cue">SCROLL TO EXPLORE ↓</a></section>'''
home=hero+class_section('stat-strip')+'<div id="overview">'+section('about')+'</div>'+section('services')
home+=photo_feature('components.webp','BUILT AROUND YOUR COMPONENT','Different applications.<br>One connected approach.','From housings and covers to industrial components and battery packing items, every part starts with its application. Explore our materials and discuss the grade, geometry and finish your project needs.','/materials','Explore materials & applications')
home+='''<section class="section navy discovery"><div class="wrap"><p class="eyebrow">EXPLORE OUR WORLD</p><div class="section-heading"><h2>Go beyond the brochure.</h2><p>Meet the company, see the equipment and understand the process behind every part.</p></div><div class="discovery-grid">'''+''.join(f'<a class="discovery-card" href="/{route}"><img src="/assets/{image}" alt="{title}" loading="lazy"><div><span>{sub}</span><h3>{title} ↗</h3></div></a>' for route,image,sub,title in [('about','factory.webp','OUR COMPANY','Two decades of experience'),('infrastructure','tooling-floor.webp','OUR INFRASTRUCTURE','Inside the tool room'),('quality','measuring.webp','OUR APPROACH','Quality, stage by stage')])+'''</div></div></section>'''+class_section('catalogue-band')+cta()
document('index','Precision in Plastic. Strength in Every Part.','Plastic injection moulding, tool design and mould development in Bangalore. Explore Shakthi Enterprises, our infrastructure and interactive catalogue.',home)

about=banner('Our story','A manufacturing partner.<br><em>A lasting relationship.</em>','Established in 2006, Shakthi Enterprises connects design, tooling and production with a customer-first approach.','factory.webp')+section('about')
about+=cards([('Our mission','Make high-quality precision moulds and parts at a competitive price, supported by service that responds to our customers’ requirements.'),('Our vision','Be a total-solutions global provider for moulds, injection parts and components, building capability through practical engineering and continuous improvement.'),('Our values','Customer satisfaction comes first. We aim to respond speedily, courteously and effectively as project requirements evolve.')],'A clear purpose behind the work.','WHAT GUIDES US')
about+=photo_feature('tooling-floor.webp','ONE ROOF ADVANTAGE','Fewer handovers.<br>Closer collaboration.','Designers, toolmakers, setters and operators work within one connected manufacturing process. This helps us discuss practical design improvements early and coordinate machining, trials, repairs and inspection.','/services','Explore our process')
about+=cards([('One point of contact','Project coordination connects your team with design, the tool room and production, so questions reach the people who can answer them.'),('Progress you can see','Weekly progress reports and digital pictures keep you informed as your project moves through the manufacturing stages.'),('Support beyond the first delivery','Our services include mould maintenance, repairs, modifications and after-sales support for ongoing manufacturing needs.')],'A partnership that stays connected.','WORKING WITH SHAKTHI')+cta()
document('about','Our Story','Meet Shakthi Enterprises, a Bangalore manufacturer established in 2006. Our mission, capabilities and approach to long-term manufacturing partnerships.',about)

