equipment=[('milling.webp','Milling','tooling','Universal milling for mould bases, cavities, cores and fixtures.'),('grinding.webp','Surface grinding','tooling','Precision flat finishing of mould plates, inserts and tool components.'),('lathe.webp','Heavy duty lathe','tooling','Turning shafts, bushes, sleeves and round tooling components.'),('drilling.webp','Vertical drilling','tooling','Drilling and tapping for ejector, cooling and fastening features.'),('wire-edm.webp','Wire-cut EDM','tooling','Intricate profiles and inserts that require precise cuts.'),('measuring.webp','Measuring instruments','inspection','Calipers, micrometers, dial and bore gauges for dimensional inspection.'),('production.webp','Moulding floor','production','Injection moulding production with material handling and process control.'),('materials-floor.webp','Material processing','production','Storage and regrind processing to support manufacturing requirements.'),('tooling-floor.webp','Tooling workspace','inspection','Machining, tooling and final inspection within the same workflow.')]
gallery='<section class="section equipment-gallery"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">TAKE A CLOSER LOOK</p><h2>Explore the equipment.</h2></div><p>Choose an area below. Select any image for a closer look.</p></div><div class="filter-bar" aria-label="Equipment categories">'+''.join(f'<button data-filter="{v}" aria-pressed="{str(i==0).lower()}">{l}</button>' for i,(v,l) in enumerate([('all','All equipment'),('tooling','Tool room'),('production','Production'),('inspection','Inspection')]))+'</div><div class="equipment-grid">'+''.join(f'<article data-category="{cat}"><button class="gallery-image" data-zoom="/assets/{img}" data-caption="{title}" aria-label="Enlarge {title}"><img src="/assets/{img}" alt="{title}" loading="lazy"><span>Expand ↗</span></button><div><h3>{title}</h3><p>{desc}</p></div></article>' for img,title,cat,desc in equipment)+'</div></div></section>'
infrastructure=banner('Infrastructure','Equipped for precision.<br><em>Built for possibility.</em>','Explore our moulding capacity, in-house tool room and inspection equipment.','tooling-floor.webp')+section('machinery')+gallery+cards([('40–100 tonne range','Smaller moulding machines support compact components. Match the part’s material, geometry and mould design to the appropriate machine.'),('160–170 tonne range','Our medium- and high-speed machines broaden the production options for intermediate component requirements.'),('530 tonne capacity','Our largest machine supports components up to approximately 2.2 kg, subject to the material, geometry and mould design.')],'Capacity matched to the component.','PRODUCTION PLANNING')+cta()
document('infrastructure','Infrastructure & Machinery','Explore 40–530 tonne injection moulding capacity, in-house tool room machinery and precision inspection equipment.',infrastructure)

